%% De forma que la temperatura se va decreciendo el cálculo de potencia eléctricafunction [kontador,y]=grafikoa2(a,b,Sp,Sn,Rp,Rn,Tdif,N,Ap,An,Lp,Ln,izena,j,p,r1,y1,r2,y2,r3,y3,r4,y4,r5,y5,r6,y6,Ti,opt)  n=300;  x=linspace(a,b,n+1);##  lim=25;##  j=(Tdif-lim)/p;  if opt==1  for i=0:j  numeros=[(Tdif-p*i)+Ti,Ti];  T_b=mean(numeros);    Sp_b=aurkitu(T_b,r1,y1)    Sn_b=aurkitu(T_b,r2,y2)    Rp_b=aurkitu(T_b,r3,y3)    Rn_b=aurkitu(T_b,r4,y4)##    Kp_b=aurkitu(T_b,r5,y5)##    Kn_b=aurkitu(T_b,r6,y6)    f=@(x) (x*(Sp_b+Sn_b)*(Tdif-p*i)-x.^2*(Lp*Rp_b/Ap+Ln*Rn_b/An))*N;    if isa(f,'function_handle')==1      F=f(x);      else      F=f;      end      max(F)      Tdif-p*i      i;      figure(i+2)##      print(figure(i+2),'TFGdif',i)      plot(x,F)      xlabel("I (A)")      ylabel("P_{out} (W)")     aldagaibalioa=num2str(Tdif-p*i)     limK=40     paso=5     hasierakoK=2     l=(limK-hasierakoK)/paso     l=round(l)     for v=1:l     korrontea(v)=hasierakoK+(paso*(v-1))      end      for w=1:l         h=w+(i*l);        Potentzia(h)=aurkitu(korrontea(w),x,F)        end      title(["La curva de la potencia electrica para este gradiente de temperatura:",aldagaibalioa])      legend(izena,'Location','southoutside')      legend('boxoff')      grid on      hold on      end      else      for i=0:j   T_prop=T_prop=(T_hot-T_cold)/log(T_hot/T_cold) ;    Sp_prop=aurkitu(T_prop,r1,y1)    Sn_prop=aurkitu(T_prop,r2,y2)    Rp_prop=aurkitu(T_prop,r3,y3)    Rn_prop=aurkitu(T_prop,r4,y4)##   Kp_prop=aurkitu(T_prop,r5,y5)##   Kn_prop=aurkitu(T_prop,r6,y6)    f=@(x) (x*(Sp_prop+Sn_prop)*(Tdif-p*i)-x.^2*(Lp*Rp_prop/Ap+Ln*Rn_prop/An))*N;    if isa(f,'function_handle')==1      F=f(x);      else      F=f;      end      max(F)      Tdif-p*i;      i;      figure(i+2)      plot(x,F)      xlabel("I (A)")      ylabel("P_{out} (W)")     aldagaibalioa=num2str(Tdif-p*i)     limK=40     paso=5     hasierakoK=2     l=(limK-hasierakoK)/paso     l=round(l)     for v=1:l     korrontea(v)=hasierakoK+(paso*(v-1))      end      for w=1:l         h=w+(i*l);        Potentzia(h)=aurkitu(korrontea(w),x,F)        end             title(["La curva de la potencia electrica para este gradiente de temperatura:",aldagaibalioa])      legend(izena,'Location','southoutside')      legend('boxoff')      grid on                  end      end       kontador=(i+2);       y=Potentzia;##  print(figure(2),'TFGdif1')##  print(figure(3),'TFGdif2')##  print(figure(4),'TFGdif3')##  print(figure(5),'TFGdif4')##  print(figure(6),'TFGdif5')##  print(figure(7),'TFGdif6')##  print(figure(8),'TFGdif7')##  print(figure(9),'TFGdif8')##  print(figure(10),'TFGdif9')##  print(figure(11),'TFGdif10')##  print(figure(12),'TFGdif11')  
endfunction
